//--------------------------------------------------------------------------//

void dei_out_start_on( void *command )
{    
    dei_out_start_on_wdog = wdog_v_add_watch( (char *)__func__ , __LINE__  , 12 );	
    
    if( dei_out_start_on_wdog != NULL )
    {
        prg_out_start( TRUE );
        prg_out_smartkey_control( TRUE );
    }
    else
    {
        wdog_v_force_reset(WDOG_V_RESET_FIRMWARE,(char*)__func__,__LINE__);
    }    

}

//--------------------------------------------------------------------------//

void dei_out_start_off( void *command )
{    
	wdog_v_release_watch(dei_out_start_on_wdog);
    
    prg_out_start( FALSE );
    prg_out_smartkey_control( FALSE );
}

